import type { WithContext, FAQPage, HowTo, SoftwareApplication } from 'schema-dts';
import type { SEOSection } from '@jjlmoya/utils-shared';
import type { ToolLocaleContent } from '../../../types';
import type { WallpaperRollCalculatorUI } from '../ui';
import { bibliography } from '../bibliography';

type Locale =
  | 'de'
  | 'en'
  | 'es'
  | 'fr'
  | 'id'
  | 'it'
  | 'ja'
  | 'ko'
  | 'nl'
  | 'pl'
  | 'pt'
  | 'ru'
  | 'sv'
  | 'tr'
  | 'zh';

interface SeoCopy {
  introTitle: string;
  introParagraph: string;
  plainTitle: string;
  plainDescription: string;
  plainPoints: string[];
  patternedTitle: string;
  patternedDescription: string;
  patternedPoints: string[];
  meaningTitle: string;
  meaningParagraph: string;
  warningTitle: string;
  warningBadge: string;
  warningHtml: string;
  summaryTitle: string;
  summaryItems: string[];
}

interface Copy {
  slug: string;
  title: string;
  description: string;
  faq: ToolLocaleContent['faq'];
  howTo: ToolLocaleContent['howTo'];
  ui: WallpaperRollCalculatorUI;
  seo: SeoCopy;
  bibliographyNames: [string, string, string];
}

const baseBibliography = (names: [string, string, string]) =>
  bibliography.map((entry, index) => ({ ...entry, name: names[index] ?? entry.name }));

function createSchemas(copy: Copy, locale: Locale) {
  const faqSchema: WithContext<FAQPage> = {
    '@context': 'https://schema.org',
    '@type': 'FAQPage',
    mainEntity: copy.faq.map((item) => ({
      '@type': 'Question',
      name: item.question,
      acceptedAnswer: { '@type': 'Answer', text: item.answer },
    })),
  };
  const howToSchema: WithContext<HowTo> = {
    '@context': 'https://schema.org',
    '@type': 'HowTo',
    name: copy.title,
    description: copy.description,
    step: copy.howTo.map((step) => ({
      '@type': 'HowToStep',
      name: step.name,
      text: step.text,
    })),
  };
  const appSchema: WithContext<SoftwareApplication> = {
    '@context': 'https://schema.org',
    '@type': 'SoftwareApplication',
    name: copy.title,
    description: copy.description,
    applicationCategory: 'UtilityApplication',
    operatingSystem: 'All',
    offers: { '@type': 'Offer', price: '0', priceCurrency: 'EUR' },
    inLanguage: locale,
  };
  return [faqSchema, howToSchema, appSchema];
}

function buildSeo(copy: Copy): SEOSection[] {
  const seo = copy.seo;
  return [
    { type: 'title', text: seo.introTitle, level: 2 },
    { type: 'paragraph', html: seo.introParagraph },
    {
      type: 'stats',
      items: [
        { value: copy.ui.labelRollsNeeded.toUpperCase(), label: copy.ui.labelDropsNeeded, icon: 'mdi:arrow-expand-horizontal' },
        { value: copy.ui.labelPatternRepeat.toUpperCase(), label: copy.ui.labelCutLength, icon: 'mdi:format-vertical-align-bottom' },
        { value: copy.ui.rollsNeededSuffix.toUpperCase(), label: copy.ui.labelRollsNeeded, icon: 'mdi:format-paint' },
      ],
      columns: 3,
    },
    {
      type: 'comparative',
      items: [
        { title: seo.plainTitle, description: seo.plainDescription, icon: 'mdi:wallpaper', points: seo.plainPoints },
        { title: seo.patternedTitle, description: seo.patternedDescription, icon: 'mdi:shape-outline', points: seo.patternedPoints },
      ],
      columns: 2,
    },
    { type: 'title', text: seo.meaningTitle, level: 3 },
    { type: 'paragraph', html: seo.meaningParagraph },
    {
      type: 'diagnostic',
      variant: 'warning',
      title: seo.warningTitle,
      icon: 'mdi:alert-outline',
      badge: seo.warningBadge,
      html: seo.warningHtml,
    },
    { type: 'summary', title: seo.summaryTitle, items: seo.summaryItems },
  ];
}

export function createWallpaperContent(locale: Locale): ToolLocaleContent<WallpaperRollCalculatorUI> {
  const copy = copies[locale];
  return {
    slug: copy.slug,
    title: copy.title,
    description: copy.description,
    ui: copy.ui,
    seo: buildSeo(copy),
    faq: copy.faq,
    bibliography: baseBibliography(copy.bibliographyNames),
    howTo: copy.howTo,
    schemas: createSchemas(copy, locale),
  };
}

