    bibliographyNames: ['Erfurt: Glasvezelbehang aanbrengen in 5 stappen', 'Graham & Brown: Behang aanbrengen', 'Wallpaperdirect: Handleiding behangen'],
    seo: { introTitle: 'Van muurmaat naar aankoopbeslissing', introParagraph: 'Behang wordt per hele rol verkocht, terwijl je een muur met verticale banen bedekt. De nuttige berekening is hoeveel banen na de patroonherhaling in één rol passen.', plainTitle: 'Effen behang', plainDescription: 'Zonder patroonmatch wordt iedere baan op de muurhoogte gesneden en deel je de rollengte door het aantal volledige banen.', plainPoints: ['Zet de herhaling op 0 cm', 'De snijlengte is de muurhoogte', 'Reststukken kunnen bruikbaar blijven'], patternedTitle: 'Behang met patroon', patternedDescription: 'Bij een herhalend motief moet iedere baan op een passend punt eindigen. De calculator rondt de snede af voordat de rolcapaciteit wordt geteld.', patternedPoints: ['Lees de herhaling op het label', 'Laat alle banen aansluiten', 'Zie extra lengte als restmateriaal'], meaningTitle: 'De uitkomst begrijpen', meaningParagraph: '<strong>Benodigde rollen</strong> is het aantal hele rollen dat je koopt. <strong>Benodigde banen</strong> zijn de verticale stroken op de muur. De <strong>snijlengte</strong> bevat de patroonmatch en de <strong>rest</strong> is de bruto lengte na het snijden.', warningTitle: 'Het productlabel blijft leidend', warningBadge: 'Belangrijke beperking', warningHtml: '<p>Fabrikanten kunnen eigen matchmethodes, batchlimieten of extra marge voorschrijven. Deze planning vervangt het label of advies van een vakman niet.</p>', summaryTitle: 'Voor je koopt', summaryItems: ['Meet de afgewerkte muurhoogte.', 'Gebruik de maten van de gekozen rol.', 'Controleer rechte, verspringende of vrije match.', 'Koop dezelfde batch als de fabrikant dat adviseert.', 'Neem genoeg rollen voor het hele project.'] },
    ui: { configTitle: 'Plan de muur', configSubtitle: 'Zet maten om in hele rollen', unitSystemLabel: 'Eenheden', unitMetric: 'Metrisch', unitImperial: 'Imperiaal', roomTitle: 'Te bedekken muur', labelRoomWidth: 'Totale muurbreedte', labelWallHeight: 'Afgewerkte muurhoogte', rollTitle: 'Rollabel', labelRollWidth: 'Rolbreedte', labelRollLength: 'Rollengte', patternTitle: 'Patroon en reserve', labelPatternRepeat: 'Patroonherhaling', patternHint: 'Gebruik de verticale herhaling van het label. Zet 0 voor effen of vrije match.', labelWasteAllowance: 'Marge voor snijverlies', wasteHint: 'Deze reserve verlaagt de bruikbare rollengte. Volg de aanbeveling van de fabrikant.', unitCentimetres: 'cm', unitInches: 'inch', unitFeet: 'ft', unitPercent: '%', resultTitle: 'Je aankoopinschatting', labelRollsNeeded: 'Hele rollen', rollsNeededSuffix: 'te kopen', labelDropsNeeded: 'Banen op de muur', labelDropsPerRoll: 'Banen per rol', labelCutLength: 'Snijlengte per baan', labelLeftover: 'Rest na snijden', visualBadge: 'Banenplanning', invalidMeasurements: 'Controleer de maten en gebruik positieve waarden.', rollTooShort: 'Deze rol is te kort voor één baan met de huidige patroon- en reservemarge.', resetLabel: 'Voorbeeld resetten' },
