    bibliographyNames: ['Erfurt: Cara memasang wallpaper dalam lima langkah', 'Graham & Brown: Cara memasang wallpaper', 'Wallpaperdirect: Panduan memasang wallpaper'],
    seo: { introTitle: 'Ubah ukuran dinding menjadi keputusan pembelian', introParagraph: 'Wallpaper dijual dalam gulungan utuh, sementara dinding ditutup oleh lajur vertikal. Perhitungan pentingnya adalah jumlah lajur yang muat setelah setiap potongan disesuaikan dengan pengulangan pola.', plainTitle: 'Wallpaper polos', plainDescription: 'Tanpa pola berulang, setiap lajur dipotong sesuai tinggi dinding dan panjang gulungan dibagi menjadi lajur utuh sebanyak mungkin.', plainPoints: ['Atur pengulangan ke 0 cm', 'Panjang potong sama dengan tinggi dinding', 'Sisa dapat digunakan jika jenis wallpaper memungkinkan'], patternedTitle: 'Wallpaper bermotif', patternedDescription: 'Pola berulang mengharuskan setiap lajur berakhir pada titik yang cocok. Kalkulator membulatkan potongan sebelum menghitung kapasitas gulungan.', patternedPoints: ['Baca pengulangan dari label', 'Selaraskan setiap lajur', 'Lihat panjang tambahan sebagai sisa'], meaningTitle: 'Arti hasilnya', meaningParagraph: '<strong>Gulungan yang diperlukan</strong> adalah jumlah gulungan utuh yang dibeli. <strong>Lajur yang diperlukan</strong> adalah strip vertikal pada dinding. <strong>Panjang potong</strong> mencakup penyesuaian pola, sedangkan <strong>sisa</strong> adalah panjang kotor yang tersisa.', warningTitle: 'Label produk tetap menjadi acuan utama', warningBadge: 'Batas penting', warningHtml: '<p>Produsen dapat menetapkan cara pencocokan, batas batch, atau cadangan tambahan. Perkiraan ini bukan pengganti label atau saran pemasang.</p>', summaryTitle: 'Sebelum membeli', summaryItems: ['Ukur tinggi akhir dinding.', 'Gunakan ukuran pada label gulungan yang dipilih.', 'Periksa pola lurus, jatuh, atau bebas.', 'Gunakan batch yang sama jika disarankan produsen.', 'Siapkan gulungan yang cukup untuk seluruh pekerjaan.'] },
