    ui: { configTitle: 'Planeie a parede', configSubtitle: 'Converta medidas em rolos completos', unitSystemLabel: 'Unidades', unitMetric: 'Métrico', unitImperial: 'Imperial', roomTitle: 'Parede a cobrir', labelRoomWidth: 'Largura total da parede', labelWallHeight: 'Altura final da parede', rollTitle: 'Etiqueta do rolo', labelRollWidth: 'Largura do rolo', labelRollLength: 'Comprimento do rolo', patternTitle: 'Rapport e reserva', labelPatternRepeat: 'Rapport', patternHint: 'Use o rapport vertical da etiqueta. Defina 0 para papel liso ou sem encaixe.', labelWasteAllowance: 'Margem de desperdício', wasteHint: 'Esta margem reduz o comprimento útil. Siga a recomendação do fabricante.', unitCentimetres: 'cm', unitInches: 'pol', unitFeet: 'pés', unitPercent: '%', resultTitle: 'A sua estimativa de compra', labelRollsNeeded: 'Rolos completos', rollsNeededSuffix: 'a comprar', labelDropsNeeded: 'Faixas na parede', labelDropsPerRoll: 'Faixas por rolo', labelCutLength: 'Corte por faixa', labelLeftover: 'Sobra após cortes', visualBadge: 'Mesa de planeamento', invalidMeasurements: 'Verifique as medidas e use valores positivos.', rollTooShort: 'Este rolo é demasiado curto para uma faixa com o rapport e a margem atuais.', resetLabel: 'Repor exemplo' },
